#include <bits/stdc++.h>
using namespace std;

long long factorial(int n) {
    long long res = 1;
    for (int i = 2; i <= n; ++i) res *= i;
    return res;
}

long long A(int n, int k) {
    return factorial(n) / factorial(n - k);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;
    if (n == 1) {
        cout << 0 << "\n";
        return 0;
    }
    vector<long long> z_list(1, 1);
    long long total_value = 0;
    for (int i = 2; i <= n; ++i) {
        int size_next_z = (i * i) / 2;
        vector<long long> next_z(size_next_z, 0);
        for (size_t j = 0; j < z_list.size(); ++j) {
            for (int k = 0; k < i; ++k) {
                if (z_list[j] > 0) {
                    next_z[i - k - 1 + j] += z_list[j];
                }
            }
        }
        vector<long long> prefix_sum(z_list.size() + 1, 0);
        for (int w = (int)z_list.size() - 1; w >= 0; --w) {
            prefix_sum[w] = (prefix_sum[w + 1] + z_list[w]) % mod;
        }
        vector<long long> e_array(prefix_sum.size(), 0);
        vector<long long> f_array(prefix_sum.size(), 0);
        for (size_t w = 0; w + 1 < prefix_sum.size(); ++w) {
            e_array[w + 1] = (e_array[w] + prefix_sum[w]) % mod;
            f_array[w + 1] = (f_array[w] - (long long)w * prefix_sum[w]) % mod;
        }
        long long total_ccc = 0;
        for (size_t jj = 0; jj < z_list.size(); ++jj) {
            int L = jj + 2;
            int R = std::min((int)z_list.size() - 1, i + (int)jj);
            long long ccc = 0;
            if (R >= L) {
                ccc = ((e_array[R + 1] - e_array[L]) * (i + 1 + (int)jj) + (f_array[R + 1] - f_array[L])) % mod;
            }
            total_ccc = (total_ccc + ccc * z_list[jj]) % mod;
        }
        total_value = (total_value + total_ccc) % mod;
        long long comb = A(n, n - i);
        total_value = (total_value + total_value * comb) % mod;
        z_list = next_z;
    }
    cout << total_value % mod << "\n";
    return 0;
}
